content.text:
{
  "name": "树莓派 GPIO 软件 SPI 接口",
  "name_en": "Raspberry Pi GPIO Software SPI Interface",
  "manufacturer": "Raspberry Pi",
  "description": "基于树莓派 GPIO 引脚实现的软件 SPI 通信接口，通过位操作模拟 SPI 总线与外部器件交换数据。适合实验室原型开发、嵌入式测试和自动化装置中连接 SPI 传感器、模数/数模转换器及其他低速 SPI 外设。",
  "description_en": "A software-implemented SPI communication interface using Raspberry Pi GPIO pins to emulate an SPI bus by bit-banging. It is suitable for laboratory prototyping, embedded testing, and automation setups that connect SPI sensors, ADC/DAC devices, and other low-speed SPI peripherals.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭软件 SPI 接口。",
      "description_en": "Close the software SPI interface."
    },
    {
      "action_name": "auto-transfer",
      "description": "通过 SPI 总线发送数据并读取返回数据。",
      "description_en": "Transfer data over the SPI bus and read back the returned data."
    },
    {
      "action_name": "auto-closed",
      "description": "获取该 SPI 接口是否已关闭。",
      "description_en": "Get whether the SPI interface is closed."
    },
    {
      "action_name": "auto-connection",
      "description": "获取与树莓派 GPIO 控制服务的连接信息。",
      "description_en": "Get the connection information for the Raspberry Pi GPIO control service."
    },
    {
      "action_name": "auto-host",
      "description": "获取所连接树莓派主机的地址。",
      "description_en": "Get the host address of the connected Raspberry Pi."
    },
    {
      "action_name": "auto-port",
      "description": "获取通信所使用的端口号。",
      "description_en": "Get the port number used for communication."
    },
    {
      "action_name": "auto-spi",
      "description": "获取当前 SPI 接口或其标识信息。",
      "description_en": "Get the current SPI interface or its identifier."
    },
    {
      "action_name": "auto-ticks",
      "description": "获取当前 GPIO 定时计数值。",
      "description_en": "Get the current GPIO timing tick value."
    },
    {
      "action_name": "auto-ticks_diff",
      "description": "获取两个定时计数值之间的差值。",
      "description_en": "Get the difference between two timing tick values."
    }
  ],
  "tag_hints": [
    "Raspberry Pi GPIO",
    "software SPI",
    "SPI communication",
    "bit-banged SPI",
    "sensor interfacing",
    "ADC/DAC control",
    "embedded prototyping"
  ]
}

